{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE redtape_db.maplemonk.returns_prime_refunds AS WITH gateway_shopify AS ( SELECT CONCAT_WS(\'-\', REPLACE(TRIM(order_name), \'#\', \'\' ), TRIM(sku)) AS order_name_n_sku, f.value::STRING AS gateway FROM redtape_db.MAPLEMONK.redtape_db_SHOPIFY_FACT_ITEMS, LATERAL FLATTEN(input => gateway) f ), return_prime_1 AS ( SELECT DISTINCT rp.order_name, RIGHT(rp.order_name,LENGTH(rp.order_name)-1), rp.returned_sku AS article, rp.beneficiary_account_number::STRING AS beneficiary_account_number, rp.item_price AS rp_amount, rp.refunded_amount refunded_amount, rp.account_holder_name, rp.ifsc_code, rp.pincode, rp.city, rp.contact, rp.email, rp.awb, rp.Customer_Address, rp.return_requested_at, rp.return_request_type, rp.shipping_courier AS logistics_partner, rp.return_facility_name AS warehouse, rp.shipping_status, CONCAT_WS(\'-\',REPLACE(TRIM(rp.order_name),\'#\',\'\'), TRIM(rp.returned_sku)) AS merge, TRIM(UPPER(LEFT(rp.ifsc_code, 4))) AS bank_code FROM redtape_db.maplemonk.redtape_RETURNSPRIME_CONSOLIDATED rp WHERE LOWER(rp.return_request_type) = \'return\' AND LOWER(rp.shipping_status) IN (\'on the way to warehouse\',\'returned to warehouse\',\'picked up from customer\') ), return_prime_2 AS ( SELECT rp1.*, bkname.\"Bank Name\" FROM return_prime_1 rp1 LEFT JOIN ( select * from maplemonk.neft_googlesheet_bank_name) bkname ON rp1.bank_code = bkname.\"Bank Code\" ), easyecom AS ( SELECT DISTINCT order_date::DATE AS order_date, reference_code, sku, selling_price AS ee_selling_price, payment_mode AS ee_payment_mode, FROM redtape_db.Maplemonk.redtape_db_EasyEcom_FACT_ITEMS ), clean AS ( SELECT ee.order_date, rp2.return_requested_at::date as return_requested_date , \'IN-TRANSIT\' AS status, REPLACE(rp2.order_name,\'#\',\'\') AS order_id, rp2.article, rp2.beneficiary_account_number, rp2.account_holder_name, rp2.rp_amount, ee.ee_selling_price AS ee_amount, ee.ee_selling_price - rp2.rp_amount AS diff_amt, rp2.rp_amount AS without_additional_charges, rp2.return_request_type, rp2.Customer_Address, rp2.ifsc_code, rp2.\"Bank Name\", rp2.pincode, rp2.city, rp2.contact customer_contact, rp2.email customer_email, ee.ee_payment_mode AS rp_mop, ee.ee_payment_mode AS ee_mop, rp2.awb, rp2.logistics_partner, rp2.warehouse, sp_gateway.gateway, rp2.shipping_status, rp2.merge, FROM return_prime_2 rp2 LEFT JOIN gateway_shopify sp_gateway ON TRIM(UPPER(rp2.merge)) = TRIM(UPPER(sp_gateway.order_name_n_sku)) LEFT JOIN easyecom ee ON REPLACE(rp2.order_name,\'#\',\'\') = ee.reference_code AND LOWER(rp2.article) = LOWER(ee.sku) WHERE LOWER(CONCAT(REPLACE(rp2.order_name,\'#\',\'\'), article)) NOT IN (SELECT LOWER(CONCAT(\"Order ID\", rp2.article)) FROM redtape_db.maplemonk.gs_neft_refund_kesar_) AND LOWER(sp_gateway.gateway) IN (\'cash on delivery (cod)\') ) SELECT * FROM clean WHERE return_requested_date >= DATE \'2026-05-01\' AND rp_mop != \'PREPAID\' ORDER BY return_requested_date",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from REDTAPE_DB.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            